//! 项目初始化取消标志注册表
//!
//! 按项目根登记正在进行的项目初始化任务. 移除工作区根时置位对应的标志,
//! 让 `load_project` 在扫描期间尽早停手, 避免加载完成后又把项目插回工作区.

use std::sync::{
    Arc,
    atomic::{AtomicBool, Ordering},
};

use path_tree::{Entry, Folder, Node};

use crate::project::canonicalize;

/// 正在进行的项目初始化任务
///
/// 每个任务在开始加载项目时登记一个取消标志, 结束后按 `Arc` 句柄移除自己那一项.
/// 标志以 `Release` 置位, 读取方以 `Acquire` 检查.
#[derive(Debug, Default)]
pub struct Initializations {
    folders: Folder<Arc<AtomicBool>>,
}

impl Initializations {
    pub fn new() -> Self {
        Self::default()
    }

    /// 登记一个项目初始化任务并返回其取消标志
    ///
    /// # Behavior
    /// * 同一根已有任务时先置位旧标志, 避免旧任务继续往工作区插入项目.
    /// * 祖先路径上已有任务时先置位旧标志, 再把该节点展开为目录.
    pub fn begin(&mut self, root: &str) -> Arc<AtomicBool> {
        let path = canonicalize(root);
        let flag = Arc::new(AtomicBool::new(false));

        match self.folders.entry(&path) {
            Ok(Entry::Occupied(mut entry)) => {
                let old = entry.insert(Node::Item(flag.clone()));
                cancel_node(&old);
            }
            Ok(Entry::Vacant(entry)) => {
                entry.insert(Node::Item(flag.clone()));
            }
            Err((_, node)) => {
                cancel_node(node);
                *node = Node::new_folder();
                self.folders.insert(&path, Node::Item(flag.clone()));
            }
        }

        flag
    }

    /// 取消根目录下全部项目初始化任务, 返回被取消的任务数量
    ///
    /// 标志与注册项一并回收; 任务结束时的 [`Self::finish`] 会因 `Arc` 不同而跳过.
    pub fn cancel_under(&mut self, root: &str) -> usize {
        let Some(node) = self.folders.remove(&canonicalize(root)) else {
            return 0;
        };
        cancel_node(&node)
    }

    /// 移除已结束任务登记的标志
    ///
    /// # Behavior
    /// * 只有当前登记的仍是同一个 `Arc` 时才移除, 避免误删同路径的新任务.
    pub fn finish(&mut self, root: &str, flag: &Arc<AtomicBool>) {
        let path = canonicalize(root);
        let is_current = self
            .folders
            .get(&path)
            .and_then(Node::as_item)
            .is_some_and(|current| Arc::ptr_eq(current, flag));
        if is_current {
            self.folders.remove(&path);
        }
    }
}

/// 置位节点及其子树中全部初始化标志, 返回数量
fn cancel_node(node: &Node<Arc<AtomicBool>>) -> usize {
    let mut count = 0;
    for (_, node) in node.iter_recursively() {
        if let Node::Item(flag) = node {
            flag.store(true, Ordering::Release);
            count += 1;
        }
    }
    count
}

